import type { ExpoConfig, ConfigContext } from "expo/config";

/** Native configuration is generated by Expo; never embed API credentials here. */
export default ({ config }: ConfigContext): ExpoConfig => {
  const development = process.env.APP_VARIANT === "development";
  const apnsEnvironment =
    process.env.APNS_ENVIRONMENT === "production"
      ? "production"
      : development
        ? "development"
        : "production";
  return {
    ...config,
    name: development ? "OpenCuria Dev" : "OpenCuria",
    slug: "opencuria",
    version: "0.1.0",
    scheme: "opencuria",
    orientation: "default",
    userInterfaceStyle: "automatic",
    // Rendered from brand/opencuria-app-icon.svg; also the Android legacy icon.
    icon: "./assets/icon.png",
    ios: {
      // iOS 18+ home screen appearances; dark keeps its alpha for the system
      // backdrop, tinted is grayscale on black.
      icon: {
        light: "./assets/icon.png",
        dark: "./assets/icon-dark.png",
        tinted: "./assets/icon-tinted.png",
      },
      bundleIdentifier: development
        ? "com.opencuria.mobile.dev"
        : "com.opencuria.mobile",
      supportsTablet: true,
      entitlements: { "aps-environment": apnsEnvironment },
      infoPlist: {
        // Camera, photo library and microphone strings come from the
        // expo-image-picker plugin below. Apps agents publish run inside
        // OpenCuria (like Expo Go) and may ask for these when opened.
        NSPhotoLibraryAddUsageDescription:
          "Save photos and videos from apps you open in OpenCuria.",
        NSLocationWhenInUseUsageDescription:
          "Share your location with apps you open in OpenCuria.",
        NSContactsUsageDescription:
          "Let apps you open in OpenCuria use your contacts.",
        NSCalendarsUsageDescription:
          "Let apps you open in OpenCuria use your calendars.",
        NSCalendarsFullAccessUsageDescription:
          "Let apps you open in OpenCuria use your calendars.",
        NSRemindersUsageDescription:
          "Let apps you open in OpenCuria use your reminders.",
        NSRemindersFullAccessUsageDescription:
          "Let apps you open in OpenCuria use your reminders.",
        NSFaceIDUsageDescription:
          "Let apps you open in OpenCuria confirm it is you.",
        NSMotionUsageDescription:
          "Let apps you open in OpenCuria use motion and fitness data.",
        // Standard HTTPS and platform crypto only; skips the export prompt.
        ITSAppUsesNonExemptEncryption: false,
        // HTTP is limited to local-network hosts (unqualified, .local, IPs).
        NSAppTransportSecurity: { NSAllowsLocalNetworking: true },
      },
    },
    android: {
      ...(process.env.GOOGLE_SERVICES_JSON
        ? { googleServicesFile: process.env.GOOGLE_SERVICES_JSON }
        : {}),
      package: development
        ? "com.opencuria.mobile.dev"
        : "com.opencuria.mobile",
      // The mark stays inside the 66dp safe zone of the 108dp canvas;
      // monochrome feeds Android 13+ themed icons.
      adaptiveIcon: {
        foregroundImage: "./assets/adaptive-icon.png",
        // Flat, like the iOS icon background in brand/opencuria-app-icon.svg.
        backgroundColor: "#0B0A14",
        monochromeImage: "./assets/adaptive-icon-monochrome.png",
      },
      // Camera for chat photos; the rest for apps agents publish, which run
      // inside OpenCuria and request them at runtime like in Expo Go.
      // Microphone and location come from expo-image-picker and expo-location.
      permissions: [
        "CAMERA",
        "READ_CONTACTS",
        "WRITE_CONTACTS",
        "READ_CALENDAR",
        "WRITE_CALENDAR",
        "READ_MEDIA_IMAGES",
        "READ_MEDIA_VIDEO",
      ],
    },
    plugins: [
      // First: Expo runs Xcode mods in reverse order, so it sees the widget target.
      "./plugins/withExtensionVersions",
      "expo-router",
      "expo-secure-store",
      [
        "expo-notifications",
        {
          defaultChannel: "agent-activity",
          icon: "./assets/notification-icon.png",
          color: "#534AB7",
        },
      ],
      [
        "expo-widgets",
        {
          enablePushNotifications: true,
          widgets: [
            {
              // Layout: src/widgets/AppsWidgetLayout.tsx.
              name: "OpenCuriaApps",
              displayName: "Apps",
              description: "Open your apps from the Home Screen.",
              ios: {
                supportedFamilies: [
                  "systemSmall",
                  "systemMedium",
                  "systemLarge",
                  "systemExtraLarge",
                ],
                // The icon grid sets its own margins, like the home screen.
                contentMarginsDisabled: true,
              },
              // Android draws its own (modules/opencuria-app-runtime).
              android: null,
            },
          ],
        },
      ],
      [
        "expo-image-picker",
        {
          photosPermission:
            "Choose photos to share with your OpenCuria agent or an app you open in OpenCuria.",
          cameraPermission:
            "Take photos for your OpenCuria conversation or an app you open in OpenCuria.",
          microphonePermission:
            "Dictate messages to your OpenCuria agent and record audio in apps you open in OpenCuria.",
        },
      ],
      [
        "expo-build-properties",
        {
          // Android cannot scope cleartext to IP ranges; normalizeServerUrl only
          // accepts http:// for local-network hosts, public hosts need https://.
          android: { usesCleartextTraffic: true },
          // Build every Expo module from source: the app runtime needs the
          // patched expo-modules-core (patches/), and a precompiled module next
          // to a source-built core links frameworks the app does not contain,
          // so iOS kills the app at launch (ExpoCameraBarcodeScanning did).
          ios: { usePrecompiledModules: false },
        },
      ],
      [
        "react-native-maps",
        // Maps in published apps: Android needs a Google Maps key at build
        // time, otherwise maps stay blank (the SDK aborts without any key).
        {
          androidGoogleMapsApiKey:
            process.env.GOOGLE_MAPS_ANDROID_API_KEY || "unconfigured",
        },
      ],
    ],
    experiments: { typedRoutes: true },
    extra: {
      eas: { projectId: "0b5e3cf0-67d2-4a79-9d66-c482ca4b6873" },
    },
  };
};
